var BASE_URL = 'https://api.mangadex.org';
var COVERS_URL = 'https://uploads.mangadex.org/covers';
var PAGE_LIMIT = 20;
var CHAPTER_LIMIT = 100;

var MANGA_INCLUDES =
  '&includes[]=cover_art&includes[]=author&includes[]=artist' +
  '&contentRating[]=safe&contentRating[]=suggestive';

function findRelationship(rels, type) {
  if (!rels) return undefined;
  for (var i = 0; i < rels.length; i++) {
    if (rels[i].type === type) return rels[i];
  }
  return undefined;
}

function extractTitle(attr) {
  var title = attr.title;
  if (!title) return 'Untitled';
  if (title.en) return title.en;
  if (title['ja-ro']) return title['ja-ro'];
  if (title.ja) return title.ja;
  var keys = Object.keys(title);
  if (keys.length > 0) return title[keys[0]];
  return 'Untitled';
}

function extractDescription(attr) {
  var desc = attr.description;
  if (!desc) return '';
  if (desc.en) return desc.en;
  var keys = Object.keys(desc);
  if (keys.length > 0) return desc[keys[0]];
  return '';
}

function extractCoverUrl(mangaId, rels) {
  var cover = findRelationship(rels, 'cover_art');
  var fileName = cover && cover.attributes && cover.attributes.fileName;
  if (fileName) {
    return COVERS_URL + '/' + mangaId + '/' + fileName + '.256.jpg';
  }
  return '';
}

function extractAuthor(rels) {
  var author = findRelationship(rels, 'author');
  return (author && author.attributes && author.attributes.name) || 'Unknown';
}

function extractArtist(rels) {
  var artist = findRelationship(rels, 'artist');
  return (artist && artist.attributes && artist.attributes.name) || extractAuthor(rels);
}

function mapStatus(status) {
  var STATUS_MAP = {
    ongoing: 'ONGOING',
    completed: 'COMPLETED',
    hiatus: 'HIATUS',
    cancelled: 'CANCELLED'
  };
  return STATUS_MAP[status] || 'UNKNOWN';
}

function extractGenres(attr) {
  var tags = attr.tags;
  if (!tags) return [];
  var genres = [];
  for (var i = 0; i < tags.length; i++) {
    var t = tags[i];
    var name = t.attributes && t.attributes.name;
    if (name) {
      if (name.en) {
        genres.push(name.en);
      } else {
        var keys = Object.keys(name);
        if (keys.length > 0) genres.push(name[keys[0]]);
      }
    }
  }
  return genres;
}

function parseMangaEntry(entry) {
  var attr = entry.attributes;
  var rels = entry.relationships || [];
  return {
    id: entry.id,
    title: extractTitle(attr),
    coverUrl: extractCoverUrl(entry.id, rels),
    author: extractAuthor(rels),
    artist: extractArtist(rels),
    description: extractDescription(attr),
    genres: extractGenres(attr),
    status: mapStatus(attr.status),
    url: BASE_URL + '/manga/' + entry.id
  };
}

function parseMangaListResponse(json) {
  var manga = [];
  if (json.data && json.data.length) {
    for (var i = 0; i < json.data.length; i++) {
      manga.push(parseMangaEntry(json.data[i]));
    }
  }
  return {
    manga: manga,
    hasNextPage: json.offset + json.limit < json.total
  };
}

var MangaDexSource = {
  name: 'MangaDex',
  version: '1.0.0',
  language: 'en',
  baseUrl: BASE_URL,
  icon: 'https://mangadex.org/favicon.ico',

  getPopularManga: function(page) {
    var offset = (page - 1) * PAGE_LIMIT;
    var url = BASE_URL + '/manga?limit=' + PAGE_LIMIT + '&offset=' + offset + '&order[followedCount]=desc' + MANGA_INCLUDES;
    return __fetchText(url).then(function(text) {
      return parseMangaListResponse(JSON.parse(text));
    });
  },

  getLatestManga: function(page) {
    var offset = (page - 1) * PAGE_LIMIT;
    var url = BASE_URL + '/manga?limit=' + PAGE_LIMIT + '&offset=' + offset + '&order[latestUploadedChapter]=desc' + MANGA_INCLUDES;
    return __fetchText(url).then(function(text) {
      return parseMangaListResponse(JSON.parse(text));
    });
  },

  searchManga: function(query, page) {
    var offset = (page - 1) * PAGE_LIMIT;
    var url = BASE_URL + '/manga?title=' + encodeURIComponent(query) + '&limit=' + PAGE_LIMIT + '&offset=' + offset + MANGA_INCLUDES;
    return __fetchText(url).then(function(text) {
      return parseMangaListResponse(JSON.parse(text));
    });
  },

  getMangaDetails: function(mangaId) {
    var url = BASE_URL + '/manga/' + mangaId + '?includes[]=cover_art&includes[]=author&includes[]=artist';
    return __fetchText(url).then(function(text) {
      var json = JSON.parse(text);
      return parseMangaEntry(json.data);
    });
  },

  getChapterList: function(mangaId) {
    var url = BASE_URL + '/manga/' + mangaId + '/feed?limit=' + CHAPTER_LIMIT + '&offset=0&translatedLanguage[]=en&order[chapter]=asc&includes[]=scanlation_group';
    return __fetchText(url).then(function(text) {
      var json = JSON.parse(text);
      var data = json.data || [];
      var filtered = [];
      for (var i = 0; i < data.length; i++) {
        var ch = data[i];
        var pageCount = ch.attributes.pages || 0;
        if (pageCount > 0) {
          filtered.push(ch);
        }
      }
      var chapters = [];
      for (var j = 0; j < filtered.length; j++) {
        var c = filtered[j];
        var attr = c.attributes;
        var rels = c.relationships || [];
        var group = findRelationship(rels, 'scanlation_group');
        var chNum = parseFloat(attr.chapter) || (j + 1);
        var title = attr.title ? ('Ch. ' + chNum + ' - ' + attr.title) : ('Chapter ' + chNum);
        chapters.push({
          id: c.id,
          mangaId: mangaId,
          title: title,
          chapterNumber: chNum,
          scanlator: (group && group.attributes && group.attributes.name) || '',
          url: BASE_URL + '/chapter/' + c.id,
          dateUploaded: new Date(attr.publishAt).getTime(),
          pageUrls: []
        });
      }
      return chapters;
    });
  },

  getPageList: function(chapterId) {
    var url = BASE_URL + '/at-home/server/' + chapterId;
    return __fetchText(url).then(function(text) {
      var json = JSON.parse(text);
      var base = json.baseUrl;
      var hash = json.chapter.hash;
      var files = json.chapter.data || [];
      var pages = [];
      for (var i = 0; i < files.length; i++) {
        pages.push(base + '/data/' + hash + '/' + files[i]);
      }
      return pages;
    });
  }
};

return MangaDexSource;
